import random
from sympy import mobius, divisors, totient
random.seed(1)
N = 500
f = {n: random.randint(-50, 50) for n in range(1, N+1)}
g = {n: sum(f[d] for d in divisors(n)) for n in range(1, N+1)}
for n in range(1, N+1):
    assert sum(mobius(d)*g[n//d] for d in divisors(n)) == f[n]
    assert sum(mobius(d)*(n//d) for d in divisors(n)) == totient(n)

from itertools import product
def primitive(s):
    n = len(s)
    return all(s != s[:d]*(n//d) for d in range(1, n) if n % d == 0)
strings = [''.join(t) for t in product('01', repeat=6)]
prim = [s for s in strings if primitive(s)]
assert len(prim) == 54 == 64-8-4+2
classes = {min(s[i:]+s[:i] for i in range(6)) for s in prim}
assert len(classes) == 9

