from sympy import primerange
def lucas(n, k, p):
    r = 1
    while n or k:
        r *= comb(n % p, k % p)
        n //= p; k //= p
    return r % p
for p in primerange(2, 20):
    for n in range(300):
        for k in range(n+1):
            assert comb(n, k) % p == lucas(n, k, p)

