from sympy import multiplicity, primerange
def carries(a, b, p):
    c = cnt = 0
    while a or b or c:
        s = a % p + b % p + c
        c = 1 if s >= p else 0
        cnt += c
        a //= p; b //= p
    return cnt
for p in primerange(2, 14):
    for n in range(1, 200):
        for k in range(n+1):
            assert multiplicity(p, comb(n, k)) == carries(k, n-k, p)

