from math import comb
for p in (2, 3, 5):
    for m in (1, 2):
        N = p**m
        copies = 0
        for I in range(p):
            for J in range(p):
                for n in range(N):
                    for k in range(N):
                        if J*N + k > I*N + n: continue
                        want = (J <= I) and k <= n and comb(n, k) % p != 0
                        assert (comb(I*N + n, J*N + k) % p != 0) == want
                if J <= I: copies += 1
        assert copies == p*(p+1)//2

